export function tankSizeFromSlider(slider: number): number {
    if (slider <= 10) {
        return PLAYER_SIZE_AT_1 + (slider - 1) / 9 * (PLAYER_SIZE_AT_10 - PLAYER_SIZE_AT_1);
    }
    return PLAYER_SIZE_AT_10 * (slider / 10);
}
