export function snapAngleToFaceMidpoint(angle: number, sides: number, bodyAngle: number, firstFace?: number): number {
    const step = (Math.PI * 2) / sides;
    const faceOffset = firstFace ?? ((sides >= 4 && sides % 2 === 0) ? 0 : step / 2);
    const offset = bodyAngle + faceOffset;
    return Math.round((angle - offset) / step) * step + offset;
}
