export function computePowerCeilingLevel(
  gm: GameModeConfig,
  maxSkillPoints: number,
  levelCap: number,
  canEarnSkillPoints: boolean = true,
): number {
  const cap = Math.max(1, Math.min(2000, levelCap));
  let last = 1;
  if (canEarnSkillPoints) {
    let prev = 0;
    for (let l = 1; l <= cap; l++) {
      let sp = expectedSpFromLeveling(l, gm, maxSkillPoints);
      if (sp > maxSkillPoints) sp = maxSkillPoints;
      if (sp > prev) last = l;
      prev = sp;
    }
  }
  if (gm.growth) {
    const start = gm.growthStartLevel ?? 1;
    const per = gm.growthPerLevel ?? 0.05;
    const maxMult = gm.growthMaxMultiplier ?? 5;
    if (per > 0 && maxMult > 1) {
      const lSize = Math.min(cap, start + Math.ceil((maxMult - 1) / per));
      if (lSize > last) last = lSize;
    }
  }
  return last;
}

