export function cleanTurretForExport(turret: Turret, layer: number = 1, hops: number = 0): object {
  const _nest = roundCanNest(layer);
  const out: any = { ...turret };

  for (let i = 0; i < EXPORT_STRIP_FIELDS.length; i++) {
    delete out[EXPORT_STRIP_FIELDS[i]];
  }

  if (out.autoSubTurrets && out.autoSubTurrets.length > 0) {
    out.autoSubTurrets = autoSubCanNest(hops)
      ? out.autoSubTurrets.map((sub: Turret) => cleanTurretForExport(sub, layer, hops + 1))
      : [];
  }

  if (out.projectileType?.customProjectileDesign?.turrets?.length) {
    out.projectileType = {
      ...out.projectileType,
      customProjectileDesign: {
        ...out.projectileType.customProjectileDesign,
        turrets: _nest ? out.projectileType.customProjectileDesign.turrets.map(
          (t: Turret) => cleanTurretForExport(t, layer + 1, 0)
        ) : [],
      },
    };
  }
  if (!_nest && out.projectileType?.subTurrets?.length) {
    out.projectileType = { ...out.projectileType, subTurrets: [] };
  }

  if (out.explode && Array.isArray(out.explode.rings)) {
    if (_nest) {
      out.explode = {
        ...out.explode,
        rings: out.explode.rings.map((r: ExplodeRing) =>
          (r && r.fragment) ? { ...r, fragment: cleanTurretForExport(r.fragment, layer + 1, 0) } : r),
      };
    } else {
      delete out.explode;
    }
  }

  return out;
}

