function computeBorderForce(
  pos: number,
  limit: number,
  _unused: number
): { force: number; damp: number } {
  const absPos = Math.abs(pos);
  if (absPos <= limit) {
    _borderResult.force = 0;
    _borderResult.damp = 1;
    return _borderResult;
  }
  const sign = pos > 0 ? -1 : 1;
  const pen = absPos - limit;
  _borderResult.force = sign * pen * BORDER_FORCE_K;
  _borderResult.damp = Math.max(0, 1 - pen / BORDER_MAX_PEN);
  return _borderResult;
}

function computeAreaBorderForce(
  pos: number,
  minBound: number,
  maxBound: number,
  _unused: number
): { force: number; damp: number } {
  if (pos >= minBound && pos <= maxBound) {
    _borderResult.force = 0;
    _borderResult.damp = 1;
    return _borderResult;
  }
  let pen: number;
  let sign: number;
  if (pos < minBound) {
    pen = minBound - pos;
    sign = 1;
  } else {
    pen = pos - maxBound;
    sign = -1;
  }
  _borderResult.force = sign * pen * BORDER_FORCE_K;
  _borderResult.damp = Math.max(0, 1 - pen / BORDER_MAX_PEN);
  return _borderResult;
}


