  private _fillAimSelfVel(enemy: EnemyTank, mainTurret: Turret | null | undefined): void {
    this._aimSelfVX = 0; this._aimSelfVY = 0;
    if (AI_CONSTANTS.AIM_SELF_MOTION === 0 || !mainTurret) return;
    const _mt = _deriveMotionType(mainTurret.projectileBehaviors,
      mainTurret.projectileType?.motionType || 'glide');
    if (_mt !== 'glide') return;
    const f = this.state.velocityInheritance / 100;
    this._aimSelfVX = enemy.velocity.x * f;
    this._aimSelfVY = enemy.velocity.y * f;
  }

  private readonly _aiAimBarrelPos: Vector = new Vector(0, 0);
  private _aimBarrelTarget(
    interceptResult: Vector, turretBasePos: Vector, bulletSpeed: number,
  ): Vector {
    if (this._aimSelfVX === 0 && this._aimSelfVY === 0) return interceptResult;
    return applySelfMotionAim(this._aiAimBarrelPos,
      turretBasePos.x, turretBasePos.y, interceptResult.x, interceptResult.y,
      bulletSpeed, this._aimSelfVX, this._aimSelfVY)
      ? this._aiAimBarrelPos : interceptResult;
  }
  private _tallyAimSelf(bulletSpeed: number): void {
    if (AI_CONSTANTS.AIM_SELF_MOTION === 0 || bulletSpeed <= 0) return;
    const wx = this._aimSelfVX, wy = this._aimSelfVY;
    const w = Math.sqrt(wx * wx + wy * wy);
    if (w < 0.01) return;
    this.aimSelfSolves++;
    this.aimSelfDegSum += Math.atan(w / bulletSpeed) * 180 / Math.PI;
  }
  public aimDecelSolves = 0;
  public aimDecelGainSum = 0;
  public aimGunSwaps = 0;
  public aimGodlySamples = 0;
