  private _tallyAimDecel(): void {
    if (!AIM_DECEL_PROBE.ran) return;
    this.aimDecelSolves++;
    this.aimDecelGainSum += AIM_DECEL_PROBE.gain;
  }
  private _targetSweep(enemy: EnemyTank, dtFactor: number): number {
    if (AI_CONSTANTS.TURN_FEED_FORWARD !== 0 && dtFactor > 0) {
      const _ffRate = normalizeAngle(enemy.targetAngle - enemy.prevTargetAngle) / (dtFactor / 60);
      if (_ffRate <= AI_CONSTANTS.TURN_FEED_FORWARD_MAX_RAD_S &&
          _ffRate >= -AI_CONSTANTS.TURN_FEED_FORWARD_MAX_RAD_S) {
        return _ffRate;
      }
    }
    return 0;
  }
  private _aimMountR = 0;
  private _aimMountBearing = 0;
  private readonly _aimMountOut: MountAimResult = { angle: 0, solvable: true };
  private _fillAimMount(enemy: EnemyTank, t: Turret | null | undefined): void {
    this._aimMountR = 0; this._aimMountBearing = 0;
    if (!t) return;
    let layerAngle = 0;
    let layerSizeRatio = 1;
    const bl = enemy.bodyLayers;
    for (let li = 0; bl && li < bl.length; li++) {
      if (bl[li].turretIds.indexOf(t.id) !== -1) {
        if (layerStandsStill(bl[li])) return;
        layerAngle = bl[li]._currentAngle;
        layerSizeRatio = bl[li].sizeRatio;
        break;
      }
    }
    const effectiveSize = enemy.size * layerSizeRatio;
    const offX = t.xOffset * effectiveSize / 2;
    const offY = t.yOffset * effectiveSize / 2;
    const r = Math.sqrt(offX * offX + offY * offY);
    if (!(r > 1e-6)) return;
    this._aimMountR = r;
    this._aimMountBearing = layerAngle + Math.atan2(offY, offX);
  }

  private _aimMountWorldAngle(enemy: EnemyTank, t: Turret | null | undefined,
                              aimX: number, aimY: number, fallbackWorld: number): number {
    if (AI_CONSTANTS.AIM_MOUNT_EXACT === 0 || !t) return fallbackWorld;
    if (enemy.forceAutospin || enemy.baseSpinEnabled || enemy.facingType === 'faceMotion') return fallbackWorld;
    this._fillAimMount(enemy, t);
    const r = this._aimMountR;
    if (!(r > 1e-6)) return fallbackWorld;
    const c = (enemy.facingType === 'faceTarget' || enemy.facingType === 'smoothFaceTarget')
      ? enemy.aimNoseOff : (t.angle || 0);
    solveMountAimInto(this._aimMountOut, aimX, aimY, enemy.position.x, enemy.position.y,
      r, this._aimMountBearing, c);
    const world = normalizeAngle(this._aimMountOut.angle + c);
    if (!this._aimMountOut.solvable) {
      this.aimMountSingularMs += this._amDtMs;
    } else {
      let corr = normalizeAngle(world - fallbackWorld);
      if (corr < 0) corr = -corr;
      const corrDeg = corr * 180 / Math.PI;
      if (corrDeg > this.aimMountCorrDegMax) this.aimMountCorrDegMax = corrDeg;
    }
    enemy.targetTurretAngle = normalizeAngle(world - (t.angle || 0));
    return world;
  }

  private _ringBodyAt = NaN;
  private _aimGunSpeed = 5;
  private _aimGunTsr = 1;
  private _aimGunDamp = glideDampPerFrame();
  private _firingGunSpeed(enemy: EnemyTank, mainTurret: Turret): number {
    let gun = mainTurret;
    if (AI_CONSTANTS.AIM_GUN_TRUTH !== 0 && !_aimGunCanFire(gun)) {
      const alt = enemy._aimGunIdx;
      if (alt !== undefined && alt >= 0 && alt < enemy.turrets.length) gun = enemy.turrets[alt];
    }
    const speedMult = getEnemyStatMultiplier(enemy, 'bulletSpeed');
    const _sct = gun.projectileType?.statCalculatorType;
    const _eff = (AI_CONSTANTS.AIM_GUN_TRUTH !== 0 && _sct === 'sustainedLowspeed')
      ? (gun.speed + 5) + (speedMult - 1)
      : (gun.speed + 5) * speedMult;
    return (10 / this.movementZoom) * _eff / 10;
  }
  private _fillAimGun(enemy: EnemyTank, mainTurret: Turret | null | undefined): void {
    this._aimGunSpeed = 5; this._aimGunTsr = 1; this._aimGunDamp = glideDampPerFrame();
    if (!mainTurret) return;
    let gun = mainTurret;
    if (AI_CONSTANTS.AIM_GUN_TRUTH !== 0 && !_aimGunCanFire(gun)) {
      const alt = enemy._aimGunIdx;
      if (alt !== undefined && alt >= 0 && alt < enemy.turrets.length) {
        gun = enemy.turrets[alt]; this.aimGunSwaps++;
      }
    }
    this.aimGodlySamples++;
    this.aimSharpenSum += aimSharpenAlpha(enemy.aimbotStrength);
    const speedMult = getEnemyStatMultiplier(enemy, 'bulletSpeed');
    const _sct = gun.projectileType?.statCalculatorType;
    const _eff = (AI_CONSTANTS.AIM_GUN_TRUTH !== 0 && _sct === 'sustainedLowspeed')
      ? (gun.speed + 5) + (speedMult - 1)
      : (gun.speed + 5) * speedMult;
    this._aimGunSpeed = (10 / this.movementZoom) * _eff / 10;
    if (AI_CONSTANTS.AIM_FLIGHT_DECEL !== 0) {
      const _mt = _deriveMotionType(gun.projectileBehaviors, gun.projectileType?.motionType || 'glide');
      if (_mt === 'glide') {
        const _tsr = gun.projectileType?.topSpeedRatio;
        if (typeof _tsr === 'number' && _tsr > 0 && _tsr < 1) this._aimGunTsr = _tsr;
        if (AI_CONSTANTS.PROJ_FRICTION_LIVE !== 0 && _motionFrictionAuthored(gun.projectileBehaviors)) {
          const _gf = _deriveMotionFriction(gun.projectileBehaviors, gun.projectileType?.friction ?? 0);
          this._aimGunDamp = _gf > 0
            ? Math.exp(Math.log(1 / (1 + _gf)) * (frictionTickRate() / 60))
            : 1;
        }
      }
    }
  }
  private _standoffReach(enemy: EnemyTank): number {
    const turrets = enemy.turrets;
    if (!turrets || turrets.length === 0) return 0;
    let gun = turrets[enemy.primaryTurretIndex];
    if (!gun || !_aimGunCanFire(gun)) {
      const alt = enemy._aimGunIdx;
      if (alt === undefined || alt < 0 || alt >= turrets.length) return 0;
      gun = turrets[alt];
      if (!gun || !_aimGunCanFire(gun)) return 0;
    }
    const pt = gun.projectileType;
    let mt = _deriveMotionType(gun.projectileBehaviors, pt?.motionType || 'glide');
    const behaviors = gun.projectileBehaviors;
    if (mt === 'glide' && behaviors) {
      for (let bi = 0; bi < behaviors.length; bi++) {
        const bh = behaviors[bi];
        if (bh.enabled && (
          bh.type === 'followMouse' || bh.type === 'autoTargetEnemy' ||
          bh.type === 'hangNearOwner' || bh.type === 'hangNearOwnerV2' || bh.type === 'minionControl' ||
          bh.type === 'goToTarget' || bh.type === 'swarmAI'
        )) { mt = 'motor'; break; }
      }
    }
    if (mt !== 'glide') return 0;
    const tsr = pt?.topSpeedRatio ?? 1;
    if (!(tsr > 0)) return 0;
    const speedMult = getEnemyStatMultiplier(enemy, 'bulletSpeed');
    const _sct = pt?.statCalculatorType;
    const _eff = _sct === 'sustainedLowspeed'
      ? (gun.speed + 5) + (speedMult - 1)
      : (gun.speed + 5) * speedMult;
    const s0 = (10 / this.movementZoom) * _eff / 10;
    if (!(s0 > 0)) return 0;
    let maxAge = (_sct === 'trap' || _sct === 'sustained' || _sct === 'sustainedLowspeed')
      ? (gun.bulletLifetime ?? 3)
      : (gun.bulletLifetime ?? 3) / Math.sqrt(speedMult);
    if (pt && pt.lifetime > 0) maxAge = ARRAS_PARITY.LIFE_BY_SPEED !== 0 ? lifeBySpeed(pt.lifetime, speedMult, _sct) : pt.lifetime;
    if (!(maxAge > 0)) return 0;
    const n = maxAge * 60;
    if (tsr >= 1) return s0 * n;
    const sEq = s0 * tsr;
    let _k = glideDampPerFrame();
    if (AI_CONSTANTS.PROJ_FRICTION_LIVE !== 0 && _motionFrictionAuthored(gun.projectileBehaviors)) {
      const _rf = _deriveMotionFriction(gun.projectileBehaviors, pt?.friction ?? 0);
      _k = _rf > 0 ? Math.exp(Math.log(1 / (1 + _rf)) * (frictionTickRate() / 60)) : 1;
    }
    const _oneMinusK = 1 - _k;
    if (_oneMinusK <= 1e-9) return s0 * n;
    return sEq * n + (s0 - sEq) * (1 - Math.pow(_k, n)) / _oneMinusK;
  }

