  private _standoffClamp(enemy: EnemyTank, base: number, losOk: boolean): number {
    const reach = this._standoffReach(enemy);
    this._soReach = reach;
    if (reach <= 0 || AI_CONSTANTS.STANDOFF_REACH === 0) return base;
    const hi = reach * AI_CONSTANTS.STANDOFF_MAX_FRAC;
    if (base > hi) { this.standoffPullMs += this._soDtMs; return hi; }
    if (AI_CONSTANTS.STANDOFF_PUSH_LOS !== 0 && !losOk) return base;
    let lo = reach * AI_CONSTANTS.STANDOFF_MIN_FRAC;
    const push = base * AI_CONSTANTS.STANDOFF_PUSH_MAX;
    if (lo > push) lo = push;
    if (lo > hi) lo = hi;
    if (base < lo) { this.standoffPushMs += this._soDtMs; return lo; }
    return base;
  }
