  constructor(initialState: GameState) {
    this.state = JSON.parse(JSON.stringify(initialState));
    this.tankPos = new Vector(0, 0);
    this.tankVelocity = new Vector(0, 0);
    this.knockbackVelocity = new Vector(0, 0);
    this.smoothedPlayerVelocity = new Vector(0, 0);
    this._prevInvisDamageTime = 0;
    this._lastPlayerFireTime = 0;
    this.spatialHash = new SpatialHash(150);
    this.shapeCollisionHash = new SpatialHash(SHAPE_FAT_CELL);
    this.combatHash = new CombatSpatialHash(100);
    this._boundFindEnemy = this.findNearestEnemyForController.bind(this);
    this._boundFindShape = this.findNearestShapeForController.bind(this);
    this._boundFindEnemyById = this.findEnemyByIdForController.bind(this);
    this._boundFindHealTarget = this.findHealOrEnemyForController.bind(this);
    this._boundFindHealTargetById = this.findHealOrEnemyByIdForController.bind(this);
    this._boundHealRescan = this.findNearestHealTargetForController.bind(this);
    this._boundHealAlly = this._ctlHealAlly.bind(this);
    this._boundFindShapeById = this.findShapeByIdForController.bind(this);
    this._boundFindCrasher = this.findNearestCrasherForController.bind(this);
    this._boundFindCrasherById = this.findCrasherByIdForController.bind(this);
    this._boundCheckLOS = this._autoTurretHasLOS.bind(this);
    this._loadPlayerName();
    try { localStorage.removeItem(TEAM_BOT_SETTINGS_KEY); } catch { }
    try { localStorage.removeItem(RESPAWN_SETTINGS_KEY); } catch { }
    this.updateEditorFov();
    this.zoom = this.targetZoom;
    this.updateMovementZoom();
  }

  public setTeamBotSettings(key: TeamBotKey, settings: TeamBotSettings): void {
    const clean = createDefaultTeamBotSettings();
    const num = (v: number, min: number, max: number, fallback: number): number =>
      Number.isFinite(v) ? Math.max(min, Math.min(max, Math.round(v))) : fallback;
    clean.overridden = settings.overridden === true;
    clean.baseLevel = num(settings.baseLevel, 0, 100, clean.baseLevel);
    clean.aimbotStrength = num(settings.aimbotStrength, 0, 100, clean.aimbotStrength);
    clean.turnSpeed = num(settings.turnSpeed, 0, 100, clean.turnSpeed);
    clean.upgradeLogic = settings.upgradeLogic;
    clean.forceAutospin = settings.forceAutospin === true;
    clean.forceAutoshoot = settings.forceAutoshoot === true;
    clean.useHardcodedColor = settings.useHardcodedColor === true;
    this.updateState({
      teamBotSettings: { ...this.state.teamBotSettings, [key]: clean },
    });
  }

  private _loadPlayerName(): void {
    try {
      const raw = localStorage.getItem(PLAYER_NAME_KEY);
      if (typeof raw === 'string') this.state.playerName = _sanitisePlayerName(raw);
    } catch { }
  }

  public setPlayerName(name: string): void {
    this.updateState({ playerName: _sanitisePlayerName(name) });
    if (MISSING_MODES.ON !== 0 && this.state.isTestMode) this.clanOfPlayer();
    try {
      localStorage.setItem(PLAYER_NAME_KEY, this.state.playerName);
    } catch { }
  }

  public getPlayerDisplayName(): string {
    return this.playerShownName() || PLAYER_NAME_FALLBACK;
  }

  private _wornName: string | null = null;
  public playerShownName(): string {
    return this._wornName ?? this.state.playerName;
  }

  public setRespawnSettings(patch: Partial<Pick<GameState, 'respawnLevelPercent' | 'respawnMinLevel' | 'respawnMaxLevel'>>): void {
    const num = (v: number, min: number, max: number, fallback: number): number =>
      Number.isFinite(v) ? Math.max(min, Math.min(max, Math.round(v))) : fallback;
    const next: Partial<GameState> = {};
    if (patch.respawnLevelPercent !== undefined) {
      next.respawnLevelPercent = num(patch.respawnLevelPercent, 0, 100, this.state.respawnLevelPercent);
    }
    if (patch.respawnMinLevel !== undefined) {
      next.respawnMinLevel = num(patch.respawnMinLevel, 0, 1000, this.state.respawnMinLevel);
    }
    if (patch.respawnMaxLevel !== undefined) {
      next.respawnMaxLevel = num(patch.respawnMaxLevel, 0, 1000, this.state.respawnMaxLevel);
    }
    this.updateState(next);
  }

  initWebGL(): void {
    if (this.webglRenderer) {
      this.webglRenderer.dispose();
      this.webglRenderer = null;
    }
    const glRenderer = new WebGLBulletRenderer();
    if (glRenderer.init()) {
      this.webglRenderer = glRenderer;
    }
  }

  private markStateChanged() {
    this.stateChangePending = true;
  }

  private flushStateChange() {
    if (!this.stateChangePending || !this.onStateChange) return;

    const now = performance.now();
    if (now - this.lastStateChangeTime >= this.STATE_CHANGE_THROTTLE_MS) {
      this.onStateChange(this.state);
      this.lastStateChangeTime = now;
      this.stateChangePending = false;
    }
  }

  private notifyStateChangeImmediate() {
    if (this.onStateChange) {
      this.onStateChange(this.state);
      this.lastStateChangeTime = performance.now();
      this.stateChangePending = false;
    }
  }

