    if (L >= prev) return;
    const hp0 = st.tankHP * this.getStatMultiplier('maxHealth'), sh0 = st.tankShieldCapacity * this.getStatMultiplier('shieldCapacity');
    let spent = 0;
    for (let i = 0; i < _UPGRADE_KEYS.length; i++) spent += st.upgrades[_UPGRADE_KEYS[i]];
    st.skillPoints += debugLevelSpDelta(prev, L, st.gameModeConfig, st.maxSkillPoints, st.bonusSkillPoints, spent + st.skillPoints, st.canEarnSkillPoints);
    st.level = L;
