  private _syncChildrenSkillsOf(
    ownerId: string, turrets: Turret[], up: Record<string, number>, cap: number, level: number,
    speedMult: number, rldMult: number, gr: GrowthRules | undefined,
  ): void {
    let anySync = false;
    for (let ti = 0; ti < turrets.length && !anySync; ti++) {
      const t = turrets[ti];
      if (t.syncsSkills) { anySync = true; break; }
      const subs = t.autoSubTurrets;
      if (subs) for (let si = 0; si < subs.length; si++) if (subs[si].syncsSkills) { anySync = true; break; }
    }
    if (!anySync) return;
    const zoom = this.movementZoom;
    const skDam = up.bulletDamage ?? 0, skPen = up.bulletPenetration ?? 0;
    const skStr = up.bulletHealth ?? 0, skSpd = up.bulletSpeed ?? 0;
    for (let bi = 0; bi < this.bullets.length; bi++) {
      const b = this.bullets[bi];
      if (!b.active || b.isFading || b.ownerId !== ownerId || b.generation !== 0) continue;
      const sid = b.sourceTurretId;
      if (sid === '') continue;
      let gun: Turret | null = null;
      let mainGun = false;
      for (let ti = 0; ti < turrets.length && gun === null; ti++) {
        const t = turrets[ti];
        if (t.id === sid) { gun = t; mainGun = true; break; }
        const subs = t.autoSubTurrets;
        if (subs) for (let si = 0; si < subs.length; si++) if (subs[si].id === sid) { gun = subs[si]; break; }
      }
      if (gun === null || !gun.syncsSkills) continue;
      const mt = _deriveMotionType(gun.projectileBehaviors, gun.projectileType?.motionType || 'glide');
      const bs = computeBulletTypeStats(gun, mt, up, cap, level, gr);
      const gss = mainGun && typeof gun.gunStatScale === 'number' ? gun.gunStatScale : 1;
      const nlm = b.necroLabyMult;
      const ratio = b.maxHealth > 0 ? b.health / b.maxHealth : 1;
      b.damage = bs.damage * gss * nlm;
      b.penetration = bs.penetration * gss * nlm;
      b.maxHealth = bs.health * gss * nlm;
      b.health = b.maxHealth * ratio;
      _btExtrasTo(b);
      b.resist = bs.resist;
      if (b.motionType === 'motor' || b.motionType === 'minion' || b.motionType === 'chase' || b.motionType === 'swarm') {
        const sct = gun.projectileType?.statCalculatorType;
        const eff = sct === 'sustainedLowspeed' ? (gun.speed + 5) + (speedMult - 1) : (gun.speed + 5) * speedMult;
        const cruise = ((10 / zoom) * eff) / 10;
        b.initialSpeed = SMALL_FIX.R766C !== 0 && cruise < 0 ? -cruise : cruise;
        if (b.inExitPhase) b.exitStoredSpeed = cruise;
      }
      b._skDam = skDam; b._skPen = skPen; b._skStr = skStr; b._skSpd = skSpd;
      b._skCap = cap; b._skRldMult = rldMult;
      this._snapGrowth(b, level, gr);
    }
  }

