  public refreshPlayerEvolutionsForLevel(prevLevel: number): void {
    const s = this.state;
    if (s.level === prevLevel) return;
    if (!s.currentTankFileName || s.gameModeConfig.mode === 'sandbox' || s.playerEvolutionLocked) return;
    const evoResult = this._computeEvolutions(s.currentTankFileName, s.level);
    const prevLen = s.availableEvolutions.length;
    if (evoResult.upgrades.length > 0) {
      s.availableEvolutions = evoResult.upgrades;
      s.evolutionBranchLabels = evoResult.labels;
      if (evoResult.upgrades.length > prevLen && this._shouldShowDreadEvolutionMenu() && !this.tankDying) s.evolutionMenuVisible = true;
    } else if (s.level < prevLevel && prevLen > 0) {
      s.availableEvolutions = [];
      s.evolutionBranchLabels = [];
      s.evolutionMenuVisible = false;
    } else {
      return;
    }
    if (this.onStateChange) this.onStateChange(s);
  }

