      const fights = this._btFightOf(m) === id;
      if (!fights && !(m._tfGoalId === id && m._tfGoalSeenAt > best)) continue;
      const dx = m.position.x - e.position.x, dy = m.position.y - e.position.y;
      if (dx * dx + dy * dy > f2 || !this._btMate(e, m) || this._tankHidFrom(e, m, false)) continue;
