    if (e.isBaseProtector === true || e.isSentryEnemy || (e._mevF & (MF_STANDS | MF_ORDER)) !== 0) { if (e._mmDo !== 0) e._mmDo = 0; return; }
    const ms = this._getEnemyNavMapState(e);
