    const lx = e.position.x - ox, ly = e.position.y - oy, r = this.getEffectiveEnemyRadius(e);
    const gx = Math.floor((lx + ms.mapHalf) / cs), gy = Math.floor((ly + ms.mapHalfY) / cs);
    if (gx < 0 || gy < 0 || gx >= ms.gridCells || gy >= gcY) return;
