      const n = Number.isFinite(v) ? Math.max(0, Math.floor(v)) : 0;
      rows.push({ id: 'lb-team-' + i, label: `${TEAM_NAMES[i].toUpperCase()} - ${word(n)}`, value: n, team: i });
