  public chatClose(nowReal: number): void { this.chat.closeBox(nowReal); }
  public chatSubmit(text: string, nowReal: number): void {
    this.chat.closeBox(nowReal);
    if (CHAT.ON === 0 || !this.state.isTestMode) return;
    const t = chatCut(text);
    if (chatIsBlank(t)) return;
    const now = this.gameNow();
    if (t.charCodeAt(0) === 36) { this.chatCmd.run(t.slice(1), now); return; }
    if (!this.chat.say(CHAT_PLAYER_ID, t, now)) this.pushMessage(CHAT_MSG_SLOW_DOWN, now);
  }

