      forceAutoshoot: false, maxSpawnCount: amount, autoRevival: false, enabled: true, aimbotStrength: 25, turnSpeed: 50,
      facingType: 'primaryTurret', useHardcodedColor: boss, sourceLibraryName: item.name, isCmdBot: true,
