    const tgtVel = target.velocity.copy();
    const tgtKnock = target.knockbackVelocity.copy();
    const tgtKnShareX = target._knShareX || 0, tgtKnShareY = target._knShareY || 0;
    const tgtAngle = target.angle;
    const tgtLevel = target.level;
    const tgtXp = target.currentXp;
    const tgtUpgrades = { ...target.upgrades };
