  private _syncMultiAreaWorldOffsets(bounds: AreaBounds[]): void {
    const areas = this.state.multiAreaConfig.areas;
    for (let i = 0; i < bounds.length && i < areas.length; i++) {
      const b = bounds[i];
      const target = areas[i].id === b.id
        ? areas[i]
        : (areas.find(a => a.id === b.id) ?? areas[i]);
      target.worldOffsetX = b.centerX;
      target.worldOffsetY = b.centerY;
    }
  }

