    const prev = cfg.halloween;
    if ((prev === undefined) === (next === undefined) && (!prev || !next || (prev.eyes === next.eyes && prev.pumpkins === next.pumpkins))) return;
    this.updateState({ gameModeConfig: { ...cfg, halloween: next } });
