          const cm = a.mapConfig.customMap, fcm = f ? f.mapConfig.customMap : undefined;
          if (!f || !cm || !fcm || !cm.rocks.some(r => r.kind !== 'rock')) return a;
          return { ...a, mapConfig: { ...a.mapConfig, customMap: { ...cm, rocks: fcm.rocks } } };
