      const x0 = Math.max(0, Math.floor((a.x0 + ms.mapHalf) / cs + 1e-6)), x1 = Math.min(gc, Math.ceil((a.x1 + ms.mapHalf) / cs - 1e-6));
      const y0 = Math.max(0, Math.floor((a.y0 + ms.mapHalfY) / cs + 1e-6)), y1 = Math.min(gcY, Math.ceil((a.y1 + ms.mapHalfY) / cs - 1e-6));
