    let e = this._enemyById.get(this._specId);
    if (e === undefined && SMALL_FIX.GH617 !== 0) { const et = this.state.enemyTanks; for (let i = 0; i < et.length; i++) if (et[i].id === this._specId && et[i].active) { e = et[i]; break; } }
