    this.tankPos.x = this._specX; this.tankPos.y = this._specY;
    this.tankVelocity.x = 0; this.tankVelocity.y = 0; this.knockbackVelocity.x = 0; this.knockbackVelocity.y = 0;
    this._knShareX = 0; this._knShareY = 0;
