  private _chaseAnchorStep(
    enemy: EnemyTank, tgtId: string, tx: number, ty: number, now: number,
  ): boolean {
    const dx = tx - enemy.position.x, dy = ty - enemy.position.y;
    const gap = Math.sqrt(dx * dx + dy * dy);
    const _cfBroke = now - enemy.chaseAnchorSeenAt > AI_CONSTANTS.CHASE_ANCHOR_BREAK_MS;
    enemy.chaseAnchorSeenAt = now;
    if (enemy.chaseAnchorId !== tgtId || _cfBroke) {
      enemy.chaseAnchorId = tgtId;
      enemy.chaseAnchorGap = gap;
      enemy.chaseAnchorAt = now;
      enemy.chaseStallBilledAt = 0;
      return false;
    }
    const _cfReach = (getEnemyMoveSpeed(enemy) / this.movementZoom) * this._enemyTermFactor(enemy) * 60;
    const _cfBar = chaseFutileProgressBar(
      _cfReach, AI_CONSTANTS.CHASE_FUTILE_STALL_MS, AI_CONSTANTS.CHASE_FUTILE_PROGRESS_FRAC);
    if (enemy.chaseAnchorGap - gap >= _cfBar) {
      enemy.chaseAnchorGap = gap;
      enemy.chaseAnchorAt = now;
      enemy.chaseStallBilledAt = 0;
      return false;
    }
    return chaseFutileVerdict(
      _cfReach, enemy.chaseAnchorGap, gap, now - enemy.chaseAnchorAt,
      AI_CONSTANTS.CHASE_FUTILE_STALL_MS, AI_CONSTANTS.CHASE_FUTILE_PROGRESS_FRAC);
  }

  private _chaseFutileRefuses(enemy: EnemyTank, tgtId: string, now: number): boolean {
    if (AI_CONSTANTS.CHASE_SPEED_FUTILE === 0) return false;
    if (enemy.chaseFutileId !== tgtId || now >= enemy.chaseFutileUntil) return false;
    if (enemy.chaseFutileCountedAt !== enemy.chaseFutileUntil) {
      enemy.chaseFutileCountedAt = enemy.chaseFutileUntil;
      this.chaseFutileRefused++;
    }
    return true;
  }

  private _healGiveUp(enemy: EnemyTank, now: number): void {
    if (SMALL_FIX.CH031 && enemy.healTargetId !== '' && enemy.currentTargetId === enemy.healTargetId) {
      enemy.healTargetId = ''; enemy.healUntil = 0; enemy.healDecisionAt = now;
    }
  }
  private _healGaveUpOn(enemy: EnemyTank, id: string, now: number): boolean {
    return (enemy.unreachTargetId === id && now < enemy.unreachUntil) || this._chaseFutileRefuses(enemy, id, now);
  }

