    const lockId = turret.autoShapeLockId;
    let lockIdx = -1;
    let lockIsCrasher = false;
    let closestCrasherDistSq = Infinity;
    let closestCrasherIdx = -1;
    let closestFoodDistSq = Infinity;
    let closestFoodIdx = -1;

