          if (_sgShooterSlot >= 0 && this._sgTargetSafeFor(_sgShooterSlot, e.position.x, e.position.y, e.id === turret.autoTargetId)) continue;
          if (_raEt >= 0 && this._roundAreaIndex(e.position.x, e.position.y) !== _raEt) continue;
