  private selectBaseShapeWeighted(cfg: ShapeSpawnConfig): string | null {
    let totalW = 0;
    for (const key of BASE_SHAPE_ORDER) {
      const bc = cfg.baseShapes[key];
      if (bc && bc.enabled) totalW += bc.spawnWeight;
    }
    if (totalW <= 0) return null;
    let rand = Math.random() * totalW;
    for (const key of BASE_SHAPE_ORDER) {
      const bc = cfg.baseShapes[key];
      if (!bc || !bc.enabled) continue;
      rand -= bc.spawnWeight;
      if (rand <= 0) return key;
    }
    return BASE_SHAPE_ORDER[0];
  }

  private selectTierShapeWeighted(
    tier: 'shiny' | 'legendary',
    cfg: ShapeSpawnConfig,
  ): { key: string; isSpecial: boolean } | null {
    const weights = tier === 'shiny' ? SPAWN_TIER_WEIGHTS.shiny : SPAWN_TIER_WEIGHTS.legendary;
    const _specialMult = categoryRateMultiplier(cfg.specialShapeRateLevel ?? 0);
    let totalW = 0;
    let len = 0;
    _tierKeys.length = 0;
    _tierWeightsArr.length = 0;
    _tierIsSpecial.length = 0;
    for (const wKey in weights) {
      const rawWeight = (weights as Record<string, number>)[wKey];
      if (wKey === 'gem' || wKey === 'jewel') {
        if (cfg.specialEnabled[wKey] !== false) {
          const weight = rawWeight * _specialMult;
          _tierKeys[len] = wKey;
          _tierWeightsArr[len] = weight;
          _tierIsSpecial[len] = true;
          totalW += weight;
          len++;
        }
      } else {
        const bc = cfg.baseShapes[wKey];
        if (bc && bc.enabled) {
          _tierKeys[len] = wKey;
          _tierWeightsArr[len] = rawWeight;
          _tierIsSpecial[len] = false;
          totalW += rawWeight;
          len++;
        }
      }
    }
    if (totalW <= 0) return null;
    let rand = Math.random() * totalW;
    for (let i = 0; i < len; i++) {
      rand -= _tierWeightsArr[i];
      if (rand <= 0) {
        _tierResult.key = _tierKeys[i];
        _tierResult.isSpecial = _tierIsSpecial[i];
        return _tierResult;
      }
    }
    _tierResult.key = _tierKeys[0];
    _tierResult.isSpecial = _tierIsSpecial[0];
    return _tierResult;
  }

  private countAllShapeTypes(): typeof _shapeCounts {
    let food = 0, base = 0, rarity = 0, laby = 0, special = 0, scaledVariant = 0, crasher = 0, nest = 0;
    for (let i = 0; i < this.floatingPolygons.length; i++) {
      const p = this.floatingPolygons[i];
      if (p._mev >= 0 || p.foodZone >= 0) continue;
      if (p.nestBorn !== 0) nest++;
      if (p.isCrasher) { crasher++; continue; }
      if (p.scaleVariant === 'beta' || p.scaleVariant === 'alpha') { scaledVariant++; continue; }
      if (p.isPolyhedron) { food++; continue; }
      food++;
      if (p.labyLevel > 0) { laby++; continue; }
      const sid = p.shapeId;
      if (sid === 'gem' || sid === 'jewel') { special++; continue; }
      if (p.rarity !== 'normal') { rarity++; continue; }
      base++;
    }
    _shapeCounts.base = base;
    _shapeCounts.rarity = rarity;
    _shapeCounts.laby = laby;
    _shapeCounts.special = special;
    _shapeCounts.food = food;
    _shapeCounts.scaledVariant = scaledVariant;
    _shapeCounts.crasher = crasher;
    _shapeCounts.nest = nest;
    return _shapeCounts;
  }

  private _bucketShapesByArea(numAreas: number): void {
    for (let i = _perAreaCounts.length; i < numAreas; i++) {
      _perAreaCounts.push({ food: 0, base: 0, rarity: 0, laby: 0, special: 0, scaledVariant: 0, crasher: 0, nest: 0 });
    }
    for (let i = 0; i < numAreas; i++) {
      const c = _perAreaCounts[i];
      c.food = 0; c.base = 0; c.rarity = 0; c.laby = 0; c.special = 0;
      c.scaledVariant = 0; c.crasher = 0; c.nest = 0;
    }
    for (let i = 0; i < this.floatingPolygons.length; i++) {
      const p = this.floatingPolygons[i];
      if (p.areaIdx < 0 || p.areaIdx >= numAreas || p._mev >= 0 || p.foodZone >= 0) continue;
      const c = _perAreaCounts[p.areaIdx];
      if (p.nestBorn !== 0) c.nest++;
      if (p.isCrasher) { c.crasher++; continue; }
      if (p.scaleVariant === 'beta' || p.scaleVariant === 'alpha') { c.scaledVariant++; continue; }
      if (p.isPolyhedron) { c.food++; continue; }
      c.food++;
      if (p.labyLevel > 0) { c.laby++; continue; }
      const sid = p.shapeId;
      if (sid === 'gem' || sid === 'jewel') { c.special++; continue; }
      if (p.rarity !== 'normal') { c.rarity++; continue; }
      c.base++;
    }
  }

  public countActiveFood(): number {
    let count = 0;
    for (let i = 0; i < this.floatingPolygons.length; i++) {
      const p = this.floatingPolygons[i];
      if (!p.isCrasher) count++;
    }
    return count;
  }

  public countActiveScaledVariants(): number {
    let count = 0;
    for (let i = 0; i < this.floatingPolygons.length; i++) {
      const sv = this.floatingPolygons[i].scaleVariant;
      if (sv === 'beta' || sv === 'alpha') count++;
    }
    return count;
  }

  public countActiveCrashers(): number {
    let count = 0;
    for (let i = 0; i < this.floatingPolygons.length; i++) {
      if (this.floatingPolygons[i].isCrasher) count++;
    }
    return count;
  }

  public playerAreaShapeBudget(): { food: number; crashers: number; foodCap: number; crasherCap: number } {
    const cfg = this._shapeStatsConfig(-1);
    let areaIdx = -1;
    if (this.areaBounds.length > 0 && this.playerAreaId) {
      for (let i = 0; i < this.areaBounds.length; i++) {
        if (this.areaBounds[i].id === this.playerAreaId) { areaIdx = i; break; }
      }
    }
    let food = 0, crashers = 0;
    for (let i = 0; i < this.floatingPolygons.length; i++) {
      const p = this.floatingPolygons[i];
      if (areaIdx >= 0 && p.areaIdx !== areaIdx) continue;
      if (p._mev >= 0) continue;
      if (SMALL_FIX.GH460 && p.foodZone >= 0) continue;
      if (p.isCrasher) crashers++; else food++;
    }
    return { food, crashers, foodCap: cfg.foodCap, crasherCap: cfg.crasherCap };
  }

  public maxRarityTestMultiplier(): number {
    let m = this.state.shapeSpawnConfig.rarityTestMultiplier ?? 1;
    if (this.areaBounds.length > 0) {
      const areas = this.state.multiAreaConfig.areas;
      for (let i = 0; i < areas.length; i++) {
        const v = areas[i]?.shapeSpawnConfig?.rarityTestMultiplier ?? 1;
        if (v > m) m = v;
      }
    }
    return m;
  }

  public sentryBudget(kind: 'sentry' | 'sentinel'): number {
    const dflt = kind === 'sentry' ? 6 : 3;
    if (this.areaBounds.length === 0) {
      const c = this.state.shapeSpawnConfig;
      return (kind === 'sentry' ? c.sentryCap : c.sentinelCap) ?? dflt;
    }
    const mac = this.state.multiAreaConfig;
    let total = 0, any = false;
    for (let i = 0; i < mac.areas.length; i++) {
      if (!this._areaTakesBots(i)) continue;
      any = true;
      const c = mac.areas[i].shapeSpawnConfig;
      total += (kind === 'sentry' ? c?.sentryCap : c?.sentinelCap) ?? dflt;
    }
    if (!any) {
      const c = mac.areas[0]?.shapeSpawnConfig;
      return (kind === 'sentry' ? c?.sentryCap : c?.sentinelCap) ?? dflt;
    }
    return total;
  }

  public countActiveSentries(): number {
    let count = 0;
    for (let i = 0; i < this.state.enemyTanks.length; i++) {
      const e = this.state.enemyTanks[i];
      if (e.active && !e.isDying && e.isSentryEnemy && e.sentryTier !== 'sentinel') count++;
    }
    return count;
  }

  public countActiveSentinels(): number {
    let count = 0;
    for (let i = 0; i < this.state.enemyTanks.length; i++) {
      const e = this.state.enemyTanks[i];
      if (e.active && !e.isDying && e.isSentryEnemy && e.sentryTier === 'sentinel') count++;
    }
    return count;
  }

  private _foodBoxInside(minX: number, minY: number, maxX: number, maxY: number): boolean {
    const rows = this.mapState ? this.mapState.customAreas : undefined;
    if (!rows) return false;
    let found = false;
    for (let i = 0; i < rows.length; i++) {
      const a = rows[i];
      if (a.uid !== this._mevFoodUid || a.x1 <= minX || a.x0 >= maxX || a.y1 <= minY || a.y0 >= maxY) continue;
      if (this._mevFoodArea !== null && a.areaId !== this._mevFoodArea) continue;
      if (!found) { found = true; this._foodX0 = a.x0; this._foodY0 = a.y0; this._foodX1 = a.x1; this._foodY1 = a.y1; continue; }
      if (a.x0 < this._foodX0) this._foodX0 = a.x0;
      if (a.y0 < this._foodY0) this._foodY0 = a.y0;
      if (a.x1 > this._foodX1) this._foodX1 = a.x1;
      if (a.y1 > this._foodY1) this._foodY1 = a.y1;
    }
    return found;
  }

