                const p2SpinDir = p2.spinImpulse !== 0 ? (p2.spinImpulse > 0 ? 1 : -1) : p2.spinSign;

                p1.spinImpulse += p1SpinDir * spinFromContact / p1SpinResist * pushDampen1;
                p2.spinImpulse += p2SpinDir * spinFromContact / p2SpinResist * pushDampen2;
